head.script:
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setVal = function() {
    scwin.simulateWrapper('#gridView1_dataLayer', 'drag-n-drop', {
        dx: 100,
        dy: 100
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_column11_filter').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2list_listColumn w2list_listColumn_checkbox w2grid_customFilter_list_listColumn_checkbox')[2].click()");

    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gridView1_cell_3_1').innerText != ''", "true");

    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "1000");

    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_customFilter_scrollView').css('display') == 'none'", "true");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_column11_filter').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2list_listColumn w2list_listColumn_checkbox w2grid_customFilter_list_listColumn_checkbox')[2].click()");
    WebSquare.wUnit.addCommand("pause", "1000");

    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gridView1_cell_3_1').innerText == ''", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
